#!/usr/bin/env python3
"""Generate Verilog testbench template from port declarations."""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path


TB_TEMPLATE = """// Auto-generated testbench template
// Top module: {top_name}
// Generated by build-testbench skill — fill in stimulus logic as needed

`timescale 1ns / 1ps

module tb_{top_name}_l1;

{parameter_declarations}

{port_declarations}

{top_name}{dut_parameter_override} u_dut (
{port_connections}
);

// Default input values for L1 smoke simulation
initial begin
{input_initialization}
end

// Clock generation — edit period as needed
initial begin
    {clk_name} = 0;
    forever #5 {clk_name} = ~{clk_name};  // 100 MHz
end

// Reset generation
initial begin
    {rst_name} = {rst_assert};
    #100;
    {rst_name} = {rst_deassert};
end

// VCD dump
initial begin
    $dumpfile("log/{top_name}_l1.vcd");
    $dumpvars(0, tb_{top_name}_l1);
end

// Stimulus — user edits here
initial begin
    // TODO: Add stimulus
    #1000;
    $display("[SIM_RESULT] L1 PASS - smoke test completed");
    $finish;
end

endmodule
"""


def _detect_clk_rst_names(ports: list[dict]) -> tuple[str, str]:
    """Detect actual clock and reset signal names from port list.

    Uses substring matching (case-insensitive) so that names like
    ``i_Sys_clk``, ``APB_clk``, ``i_Rst_n`` are recognised correctly.
    """
    clk_name = "clk"
    rst_name = "rst_n"
    for p in ports:
        name = p.get("name", "")
        direction = p.get("direction", "")
        if direction != "input":
            continue
        lower = name.lower()
        if "clk" in lower or "clock" in lower:
            clk_name = name
        if "rst" in lower or "reset" in lower:
            rst_name = name
    return clk_name, rst_name


def _reset_levels(reset_name: str) -> tuple[int, int]:
    """Return asserted/deasserted levels for common active-high/low names."""
    active_low = reset_name.lower().endswith("_n") or reset_name.lower() in {
        "rstn", "resetn"
    }
    return (0, 1) if active_low else (1, 0)


def _format_width(port: dict) -> str:
    w = port.get("width", 1)
    if isinstance(w, int):
        return "[{}:0]".format(w - 1) if w > 1 else ""
    if isinstance(w, str) and w:
        return "[{}]".format(re.sub(r"\s+", "", w))
    return ""


def generate_testbench(
    top_name: str, ports: list[dict], parameters: dict[str, str] | None = None
) -> str:
    """Generate testbench source from port list."""
    working_ports = list(ports)

    # Detect actual clock/reset signal names
    clk_name, rst_name = _detect_clk_rst_names(working_ports)
    rst_assert, rst_deassert = _reset_levels(rst_name)

    # Build declarations
    decl_lines = []
    for p in working_ports:
        direction = p.get("direction", "")
        width_str = _format_width(p)
        signed_str = "signed" if p.get("signed") else ""

        parts = []
        if direction == "input":
            parts.append("reg")
        else:
            parts.append("wire")
        if signed_str:
            parts.append(signed_str)
        if width_str:
            parts.append(width_str.strip())
        parts.append(p.get("name", "") + ";")

        decl_lines.append("    " + " ".join(parts))

    port_declarations = "\n".join(decl_lines)

    # Build port connections
    conn_lines = []
    for p in working_ports:
        conn_lines.append("        .{} ({}),".format(p.get("name", ""), p.get("name", "")))
    if conn_lines:
        conn_lines[-1] = conn_lines[-1].rstrip(",")

    port_connections = "\n".join(conn_lines)

    input_initialization = "\n".join(
        "    {} = 0;".format(p.get("name", ""))
        for p in working_ports
        if p.get("direction") == "input" and p.get("name") not in {clk_name, rst_name}
    )

    parameter_declarations = "\n".join(
        "    localparam integer {} = {};".format(name, value)
        for name, value in (parameters or {}).items()
    )
    if parameters:
        override_lines = [
            "    .{} ({})".format(name, name)
            for name in parameters
        ]
        dut_parameter_override = " #(\n" + ",\n".join(override_lines) + "\n)"
    else:
        dut_parameter_override = ""
    return TB_TEMPLATE.format(
        top_name=top_name,
        parameter_declarations=parameter_declarations,
        port_declarations=port_declarations,
        port_connections=port_connections,
        input_initialization=input_initialization,
        dut_parameter_override=dut_parameter_override,
        clk_name=clk_name,
        rst_name=rst_name,
        rst_assert=rst_assert,
        rst_deassert=rst_deassert,
    )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Generate Verilog testbench template from ports."
    )
    parser.add_argument(
        "--ports-file", required=True,
        help="Path to ports JSON file (array of port objects)"
    )
    parser.add_argument("--top", required=True, help="Top module name")
    parser.add_argument("--output", required=True, help="Output testbench path")
    parser.add_argument(
        "--param", action="append", default=[], metavar="NAME=VALUE",
        help="Declare a parameter value for symbolic port widths (repeatable)",
    )
    args = parser.parse_args(argv)

    ports_path = Path(args.ports_file)
    ports = json.loads(ports_path.read_text(encoding="utf-8"))

    parameters = {}
    for item in args.param:
        if "=" not in item:
            parser.error(f"--param must use NAME=VALUE: {item}")
        name, value = item.split("=", 1)
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_$]*", name):
            parser.error(f"invalid parameter name: {name}")
        parameters[name] = value
    tb_source = generate_testbench(args.top, ports, parameters)

    output_path = Path(args.output)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(tb_source, encoding="utf-8")
    print("Testbench written to: {}".format(output_path))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
